import{_ as o,a0 as l,w as p,s as d,ao as r,I as t,x as s,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何更新 Linux 的符号链接 | LCTT x X-CMD","titleTemplate":false,"description":"如何更新 Linux 的符号链接 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何更新 Linux 的符号链接 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何更新 Linux 的符号链接 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211104 How to update a Linux symlink","title":"如何更新 Linux 的符号链接","tag":"202111","desc":""},"relativePath":"202111/20211104 How to update a Linux symlink.md","filePath":"[post].md"}'),c={name:"202111/20211104 How to update a Linux symlink.md"};function u(g,e,h,k,f,m){const n=l("Link");return p(),d("div",null,[e[15]||(e[15]=r(`<h1 id="如何更新-linux-的符号链接" tabindex="-1">如何更新 Linux 的符号链接 <a class="header-anchor" href="#如何更新-linux-的符号链接" aria-label="Permalink to “如何更新 Linux 的符号链接”">​</a></h1><blockquote><p>链接一直是 UNIX 文件系统的一个独特的高级功能。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202111/13/185626ubb832pphjhlpmly.jpg" alt=""></p><p>UNIX 和 Linux 用户发现链接有很多用途，特别是符号链接。我喜欢使用符号链接的一种方式是管理各种 IT 设备的配置备份。</p><p>我有一个目录结构，用来存放我的文档、更新及网络上其他和计算机和设备有关的文件。设备可以包括路由器、接入点、NAS 服务器和笔记本电脑，通常有不同的品牌和版本。配置备份本身可能在目录树的深处，例如 <code>/home/alan/Documents/network/device/NetgearRL5000/config</code>。</p><p>为了简化备份过程，我在主目录中有一个名为 <code>Configuration</code> 的目录。我使用这个目录的符号链接来指向特定的设备目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:~/Configuration/ $ ls -F1</span></span>
<span class="line"><span>Router@</span></span>
<span class="line"><span>Accesspoint@</span></span>
<span class="line"><span>NAS@</span></span></code></pre></div><p><strong>注意</strong>：<code>ls</code> 命令的 <code>-F</code> 选项在每个文件名上附加特殊字符以表示其类型。如上所示，<code>@</code> 符号表示这些是链接。</p><h3 id="创建一个链接" tabindex="-1">创建一个链接 <a class="header-anchor" href="#创建一个链接" aria-label="Permalink to “创建一个链接”">​</a></h3><p>符号链接 <code>Router</code> 指向我的 Netgear RL5000 的 <code>config</code> 目录。创建它的命令是 <code>ln -s</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ln -s /home/alan/Documents/network/device/NetgearRL5000/config Router</span></span></code></pre></div><p>然后，用 <code>ls -l</code> 看一下并确认：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:~/Configuration/ $ ls -l</span></span>
<span class="line"><span>Router -&gt; /home/alan/Documents/network/device/NetgearRL5000/config</span></span>
<span class="line"><span>NAS -&gt; /home/alan/Documents/network/device/NFSBox/config</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>这样做的好处是，当对这个设备进行维护时，我只需进入 <code>~/Configuration/Router</code>。</p><p>如果我决定用一个新的型号替换这个路由器，使用符号链接的第二个好处就很明显了。我可能会把旧的路由器改成一个接入点。因此，它的目录并没有被删除。相反，我有一个新的目录，对应于新的路由器，也许是华硕 DF-3760。我创建这个目录并确认它的存在：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir -p ~/Documents/network/device/ASUSDF-3760/config</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:~/Documents/network/device/ $ ls</span></span>
<span class="line"><span>NetgearRL5000</span></span>
<span class="line"><span>ASUSDF-3760</span></span>
<span class="line"><span>NFSBox</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>另一个例子是，如果你的办公室里有几个接入点。你可以使用符号链接在逻辑上代表每一个，用一个通用的名字，如 <code>ap1</code>，<code>ap2</code>，等等，或者你可以使用描述性的词语，如 <code>ap_floor2</code>，<code>ap_floor3</code>，等等。这样，当物理设备随时间变化时，你不必持续更新任何可能管理它们的进程，因为它们是在处理链接而不是实际的设备目录。</p><h3 id="更新一个链接" tabindex="-1">更新一个链接 <a class="header-anchor" href="#更新一个链接" aria-label="Permalink to “更新一个链接”">​</a></h3><p>由于我的主路由器已经改变，我想让路由器的符号链接指向它的目录。我可以使用 <code>rm</code> 和 <code>ln</code> 命令来删除和创建一个新的符号链接，但是有一种方法可以只用 <code>ln</code> 命令和几个选项就可以一步完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:~/Configuration/ $ ln -vfns ~/Documents/network/device/ASUSDF-3760/config/ Router</span></span>
<span class="line"><span>&#39;Router&#39; -&gt; &#39;/home/alan/Documents/network/device/ASUSDF-3760/config/&#39;</span></span>
<span class="line"><span>:~/Configuration/ $ ls -l</span></span>
<span class="line"><span>Router -&gt; /home/alan/Documents/network/device/ASUSDF-3760/config</span></span>
<span class="line"><span>NAS -&gt; /home/alan/Documents/network/device/NFSBox/config</span></span></code></pre></div><p>根据手册页，这些选项如下：</p><ul><li><code>-v</code>、<code>--verbose</code>：打印每个链接文件的名称</li><li><code>-f</code>、<code>--force</code>：删除目标文件（有必要，因为已经存在一个链接）</li><li><code>-n</code>、<code>--no-dereference</code>：如果链接名是一个目录的符号链接，就把它当作一个正常的文件</li><li><code>-s</code>、<code>--symbolic</code>：制作符号链接而不是硬链接</li></ul><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>链接是 UNIX 和 Linux 文件系统中最强大的功能之一。其他操作系统也曾试图模仿这种能力，但由于他们的文件系统缺乏基本的链接设计，这些系统从来没有工作得那么好，也没有那么可用。</p><p>上面的演示只是利用链接在生活生产环境中无缝浏览不断变化的目录结构的众多可能性中的一种。链接提供了一个永远不会长期静态的组织所需的灵活性。</p><hr>`,27)),t("p",null,[e[1]||(e[1]=s("via: ",-1)),a(n,{href:"https://opensource.com/article/21/11/update-linux-file-system-link"},{default:i(()=>[...e[0]||(e[0]=[s("https://opensource.com/article/21/11/update-linux-file-system-link",-1)])]),_:1})]),t("p",null,[e[6]||(e[6]=s("作者：",-1)),a(n,{href:"https://opensource.com/users/alanfdoss"},{default:i(()=>[...e[2]||(e[2]=[s("Alan Formy-Duval",-1)])]),_:1}),e[7]||(e[7]=s(" 选题：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:i(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}const v=o(c,[["render",u]]);export{C as __pageData,v as default};
